    "power-shell": "PowerShell",
    "zsh": "Zsh",
    "nushell": "Nushell",
}

# Generic usage suffixes (without program name).
USAGE: Dict[str, str] = {
    "root": "[OPTIONS] [COMMAND]",
    "add": "add [OPTIONS] <COMMAND>...",
    "remove": "remove <TASK_IDS>...",
    "switch": "switch <TASK_ID_1> <TASK_ID_2>",
    "stash": "stash [OPTIONS] [TASK_IDS]...",
    "enqueue": "enqueue [OPTIONS] [TASK_IDS]...",
    "start": "start [OPTIONS] [TASK_IDS]...",
    "restart": "restart [OPTIONS] [TASK_IDS]...",
    "pause": "pause [OPTIONS] [TASK_IDS]...",
    "kill": "kill [OPTIONS] [TASK_IDS]...",
    "send": "send <TASK_ID> <INPUT>",
    "edit": "edit [TASK_IDS]...",
    "env": "env <COMMAND>",
    "env_set": "env set <TASK_ID> <KEY> <VALUE>",
    "env_unset": "env unset <TASK_ID> <KEY>",
    "group": "group [OPTIONS] [COMMAND]",
    "group_add": "group add [OPTIONS] <NAME>",
    "group_remove": "group remove <NAME>",
    "status": "status [OPTIONS] [QUERY]...",
    "log": "log [OPTIONS] [TASK_IDS]...",
    "follow": "follow [OPTIONS] [TASK_ID]",
    "wait": "wait [OPTIONS] [TASK_IDS]...",
    "clean": "clean [OPTIONS]",
    "reset": "reset [OPTIONS]",
    "shutdown": "shutdown",
    "parallel": "parallel [OPTIONS] [PARALLEL_TASKS]",
    "completions": "completions <SHELL> [OUTPUT_DIRECTORY]",
}

# For contextual usage when a specific flag is present.
POSITIONAL_SUFFIX = {
    "add": "<COMMAND>...",
    "stash": "[TASK_IDS]...",
    "enqueue": "[TASK_IDS]...",
    "start": "[TASK_IDS]...",
    "restart": "[TASK_IDS]...",
    "pause": "[TASK_IDS]...",
    "kill": "[TASK_IDS]...",
    "status": "[QUERY]...",
    "log": "[TASK_IDS]...",
    "follow": "[TASK_ID]",
    "wait": "[TASK_IDS]...",
    "parallel": "[PARALLEL_TASKS]",
    "group_add": "<NAME>",
}

class CliExit(Exception):
    def __init__(self, code: int):
        self.code = code

class OptSpec:
    def __init__(self, long: str, usage: str, short: Optional[str] = None, takes: bool = False,
                 validator: Optional[Callable[[str, str], None]] = None, flag: bool = False):
        self.long = long
        self.usage = usage
        self.short = short
        self.takes = takes
        self.validator = validator
        self.flag = flag


def prog() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def data_dirs() -> Tuple[Path, Path]:
    script = Path(__file__).resolve()
    here = script.parent
    # When copied to ./executable, data lives in ./src/*. When run in-place, data lives next to script.
    candidates = [here / "src", here]
    for base in candidates:
        if (base / "help").is_dir() and (base / "completions").is_dir():
            return base / "help", base / "completions"
    return here / "src" / "help", here / "src" / "completions"


def load_help(key: str, long_form: bool) -> str:
    help_dir, _ = data_dirs()
    suffix = "long" if long_form else "short"
    text = (help_dir / f"{key}_{suffix}.txt").read_text()
    return text.replace("executable", prog())


def print_help(key: str, long_form: bool, to_stderr: bool = False) -> None:
    stream = sys.stderr if to_stderr else sys.stdout
    stream.write(load_help(key, long_form))
    raise CliExit(2 if to_stderr else 0)


def parse_error(message: str, usage_key: Optional[str] = None, usage_suffix: Optional[str] = None,
                tip: Optional[str] = None, possible: Optional[str] = None) -> None:
    out = [f"error: {message}\n"]
    if possible:
        out.append(f"  [possible values: {possible}]\n")
    if tip:
        out.append("\n")
        out.append(f"  tip: {tip}\n")
    out.append("\n")
    if usage_suffix is None and usage_key is not None:
        usage_suffix = USAGE[usage_key]
    if usage_suffix is not None:
        out.append(f"Usage: {prog()} {usage_suffix}\n\n")
    out.append("For more information, try '--help'.\n")
    sys.stderr.write("".join(out))
    raise CliExit(2)


def missing_value(opt_usage: str, possible: Optional[str] = None) -> None:
    parse_error(f"a value is required for '{opt_usage}' but none was supplied", possible=possible)


def missing_required(args: List[str], usage_suffix: str) -> None:
    lines = ["error: the following required arguments were not provided:\n"]
    for arg in args:
        lines.append(f"  {arg}\n")
    lines.append("\n")
    lines.append(f"Usage: {prog()} {usage_suffix}\n\n")
    lines.append("For more information, try '--help'.\n")
    sys.stderr.write("".join(lines))
    raise CliExit(2)


def unexpected(arg: str, usage_key: Optional[str] = None, usage_suffix: Optional[str] = None,
               value_tip: bool = False, custom_tip: Optional[str] = None) -> None:
    tip = custom_tip
    if tip is None and value_tip and arg.startswith("-"):
        tip = f"to pass '{arg}' as a value, use '-- {arg}'"
    parse_error(f"unexpected argument '{arg}' found", usage_key=usage_key, usage_suffix=usage_suffix, tip=tip)


def invalid_value(value: str, target: str, reason: str, possible: Optional[str] = None,
                  tip: Optional[str] = None) -> None:
    parse_error(f"invalid value '{value}' for '{target}': {reason}" if reason else
                f"invalid value '{value}' for '{target}'", possible=possible, tip=tip)


def unexpected_value(value: str, opt: str, usage_suffix: str) -> None:
    parse_error(f"unexpected value '{value}' for '{opt}' found; no more were expected",
                usage_suffix=usage_suffix)


def usage_with_option(command: str, opt_usage: str, pos_present: bool = False) -> str:
    suffix = POSITIONAL_SUFFIX.get(command, "")
    if pos_present and suffix.startswith("[") and suffix.endswith("]..."):
        # Clap tightens optional varargs to required-looking when values were already present.
        suffix = "<" + suffix[1:-4] + ">..."
    return f"{command.replace('_', ' ')} {opt_usage}" + (f" {suffix}" if suffix else "")


def normalize_command(name: str) -> str:
    return ROOT_ALIASES.get(name, name)


def levenshtein(a: str, b: str) -> int:
    if len(a) < len(b):
        a, b = b, a
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i]
        for j, cb in enumerate(b, 1):
            current.append(min(previous[j] + 1, current[j-1] + 1, previous[j-1] + (ca != cb)))
        previous = current
    return previous[-1]


def suggest_value(value: str, choices: List[str]) -> Optional[str]:
    # Good enough approximation of clap's suggestions for observed value enums.
    if not value:
        return None
    best = None
    best_score = 10**9
    compact_value = value.replace("-", "")
    for choice in choices:
        compact_choice = choice.replace("-", "")
        score = levenshtein(compact_value, compact_choice)
        if choice.startswith(value) or compact_choice.startswith(compact_value):
            score -= 2
        if score < best_score:
            best_score, best = score, choice
    if best is not None and (best_score <= 3 or best.startswith(value[:1])):
        return best
    return None


def unrecognized_subcommand(name: str, usage_key: str, choices: List[str], aliases: Optional[List[str]] = None) -> None:
    all_choices = choices + (aliases or [])
    # Reproduce common observed suggestions; otherwise use a simple edit-distance approximation.
    hard = {
        ("root", "format-status"): ["rm", "fo"],
        ("root", "foo"): ["follow", "fo"],
        ("root", "fooo"): ["follow", "fo"],
        ("root", "folow"): ["fo", "follow"],
        ("root", "rmm"): ["rm"],
        ("root", "remo"): ["rm", "re", "remove"],
        ("root", "helpp"): ["help"],
        ("env", "sett"): ["set"],
        ("env", "get"): ["set"],
        ("env", "un"): ["unset"],
        ("group", "remve"): ["remove"],
        ("group", "groups"): ["group"],
        ("group", "g"): ["group"],
    }
    suggestions = hard.get((usage_key, name))
    if suggestions is None:
        scored = []
        for c in all_choices:
            d = levenshtein(name, c)
            if name and (d <= max(2, len(name)//2) or c.startswith(name[:2]) or name.startswith(c[:2])):
                scored.append((d, c))
        scored.sort(key=lambda x: (x[0], x[1]))
        suggestions = [c for _, c in scored[:4]]
    tip = None
    if suggestions:
        quoted = ", ".join(f"'{s}'" for s in suggestions)
        if len(suggestions) == 1:
            tip = f"a similar subcommand exists: {quoted}"
        else:
            tip = f"some similar subcommands exist: {quoted}"
    parse_error(f"unrecognized subcommand '{name}'", usage_key=usage_key, tip=tip)


def validate_uint(value: str, target: str) -> None:
    if value == "":
        invalid_value(value, target, "cannot parse integer from empty string")
    if not value.isdigit():
        invalid_value(value, target, "invalid digit found in string")
    try:
        n = int(value, 10)
    except Exception:
        invalid_value(value, target, "invalid digit found in string")
    if n > 18446744073709551615:
        invalid_value(value, target, "number too large to fit in target type")


def validate_delay(value: str, target: str = "--delay <delay>") -> None:
    v = value.strip()
    if not v:
        invalid_value(value, target, "could not parse as seconds or date expression")
    if v.isdigit():
        return
    if re.match(r"^\d+\s*(s|sec|secs|second|seconds|m|min|mins|minute|minutes|h|hr|hour|hours|d|day|days|w|week|weeks|month|months)$", v, re.I):
        return
    if re.match(r"^\d+[smhdw]$", v, re.I):
        return
    # Accept common date/time-ish expressions documented by the CLI.
    weekdays = "monday tuesday wednesday thursday friday saturday sunday".split()
    months = "jan january feb february mar march apr april may jun june jul july aug august sep september oct october nov november dec december".split()
    lower = v.lower()
    if any(w in lower for w in weekdays + months):
        return
    if re.search(r"\d", v) and re.search(r"[-/:T ]|am\b|pm\b", v, re.I):
        return
    invalid_value(value, target, "could not parse as seconds or date expression")


def validate_status(value: str, target: str = "--status <STATUS>") -> None:
    if value not in {"queued", "running", "success", "done"}:
        invalid_value(value, target, "Matching variant not found")


def validate_signal(value: str, target: str = "--signal <SIGNAL>") -> None:
    lower = value.lower()
    valid_names = {"int", "sigint", "term", "sigterm", "kill", "sigkill", "cont", "sigcont", "stop", "sigstop"}
    valid_nums = {"2", "9", "15", "18", "19"}
    if lower not in valid_names and value not in valid_nums:
        invalid_value(value, target, "Matching variant not found")


def option_specs_for(command: str) -> Dict[str, OptSpec]:
    s = {}
    def add(long: str, usage: str, short: Optional[str] = None, takes: bool = False,
            validator: Optional[Callable[[str, str], None]] = None):
        s[long] = OptSpec(long, usage, short, takes, validator, flag=not takes)
    if command == "status":
        add("json", "--json", "j")
        add("group", "--group <GROUP>", "g", True)
    elif command == "log":
        add("group", "--group <GROUP>", "g", True)
        add("all", "--all", "a")
        add("json", "--json", "j")
        add("lines", "--lines <LINES>", "l", True, validate_uint)
        add("full", "--full", "f")
    elif command == "follow":
        add("lines", "--lines <LINES>", "l", True, validate_uint)
    elif command == "clean":
        add("successful-only", "--successful-only", "s")
        add("group", "--group <GROUP>", "g", True)
    elif command == "reset":
        add("groups", "--groups <GROUPS>", "g", True)
        add("force", "--force", "f")
    elif command == "parallel":
        add("group", "--group <group>", "g", True)
    elif command in {"stash", "enqueue"}:
        add("group", "--group <GROUP>", "g", True)
        add("all", "--all", "a")
        add("delay", "--delay <delay>", "d", True, validate_delay)
    elif command == "start":
        add("group", "--group <GROUP>", "g", True)
        add("all", "--all", "a")
    elif command == "pause":
        add("group", "--group <GROUP>", "g", True)
        add("all", "--all", "a")
        add("wait", "--wait", "w")
    elif command == "kill":
        add("group", "--group <GROUP>", "g", True)
        add("all", "--all", "a")
        add("signal", "--signal <SIGNAL>", "s", True, validate_signal)
    elif command == "wait":
        add("group", "--group <GROUP>", "g", True)
        add("all", "--all", "a")
        add("quiet", "--quiet", "q")
        add("status", "--status <STATUS>", "s", True, validate_status)
    elif command == "restart":
        add("all-failed", "--all-failed", "a")
        add("failed-in-group", "--failed-in-group <FAILED_IN_GROUP>", "g", True)
        add("immediate", "--immediate", "k")
        add("stashed", "--stashed", "s")
        add("in-place", "--in-place", "i")
        add("not-in-place", "--not-in-place")
        add("edit", "--edit", "e")
    return s


def spec_by_short(specs: Dict[str, OptSpec], ch: str) -> Optional[OptSpec]:
    for spec in specs.values():
        if spec.short == ch:
            return spec
    return None


def target_for_pos(command: str) -> str:
    return {
        "remove": "<TASK_IDS>...",
        "edit": "[TASK_IDS]...",
        "stash": "[TASK_IDS]...",
        "enqueue": "[TASK_IDS]...",
        "start": "[TASK_IDS]...",
        "restart": "[TASK_IDS]...",
        "pause": "[TASK_IDS]...",
        "kill": "[TASK_IDS]...",
        "wait": "[TASK_IDS]...",
        "log": "[TASK_IDS]...",
        "follow": "[TASK_ID]",
        "parallel": "[PARALLEL_TASKS]",
        "switch1": "<TASK_ID_1>",
        "switch2": "<TASK_ID_2>",
        "send": "<TASK_ID>",
        "env_set": "<TASK_ID>",
        "env_unset": "<TASK_ID>",
        "group_add_parallel": "--parallel <PARALLEL>",
    }.get(command, "<TASK_ID>")


def validate_task_list(vals: List[str], command: str) -> None:
    for v in vals:
        validate_uint(v, target_for_pos(command))


def get_option_value(args: List[str], idx: int, spec: OptSpec, command: str, has_pos_tip: bool) -> Tuple[str, int]:
    token = args[idx]
    if token.startswith("--") and "=" in token:
        return token.split("=", 1)[1], idx + 1
    # Attached short value, e.g. -o5.
    if token.startswith("-") and not token.startswith("--") and len(token) > 2 and token[1] == (spec.short or ""):
        return token[2:], idx + 1
    if idx + 1 >= len(args) or args[idx + 1] == "--":
        missing_value(spec.usage)
    if args[idx + 1].startswith("-"):
        unexpected(args[idx + 1], usage_key=command, value_tip=has_pos_tip)
    return args[idx + 1], idx + 2


def parse_generic_command(command: str, args: List[str], pos_kind: str, required_min: int = 0,
                          max_pos: Optional[int] = None, numeric: bool = False,
                          help_key: Optional[str] = None, has_pos_tip: bool = True) -> None:
    help_key = help_key or command
    specs = option_specs_for(command)
    seen_order: List[str] = []
    seen: Dict[str, bool] = {}
    pos: List[str] = []
    after_dd = False
    i = 0
    while i < len(args):
        t = args[i]
        if after_dd:
            pos.append(t); i += 1; continue
        if t == "--":
            after_dd = True; i += 1; continue
        if t == "--help":
            print_help(help_key, True)
        if t == "-h":
            print_help(help_key, False)
        if t.startswith("--"):
            nameval = t[2:]
            name, eq, value = nameval.partition("=")
            spec = specs.get(name)
            if spec is None:
                unexpected(t, usage_key=command, value_tip=has_pos_tip)
            if spec.takes:
                if eq:
                    val = value
                    i += 1
                else:
                    val, i = get_option_value(args, i, spec, command, has_pos_tip)
                if spec.validator:
                    spec.validator(val, spec.usage)
                seen[name] = True; seen_order.append(spec.usage)
            else:
                if eq:
                    unexpected_value(value, f"--{name}", usage_with_option(command, spec.usage))
                seen[name] = True; seen_order.append(spec.usage); i += 1
            continue
        if t.startswith("-") and t != "-":
            # Short options, with simple clustering support.
            if len(t) >= 2:
                j = 1
                while j < len(t):
                    ch = t[j]
                    if ch == "h":
                        print_help(help_key, False)
                    spec = spec_by_short(specs, ch)
                    if spec is None:
                        unexpected("-" + ch if len(t) > 2 else t, usage_key=command, value_tip=has_pos_tip)
                    if spec.takes:
                        if j + 1 < len(t):
                            val = t[j+1:]
                            i += 1
                        else:
                            val, i = get_option_value(args, i, spec, command, has_pos_tip)
                        if spec.validator:
                            spec.validator(val, spec.usage)
                        seen[spec.long] = True; seen_order.append(spec.usage)
                        break
                    else:
                        seen[spec.long] = True; seen_order.append(spec.usage)
                        j += 1
                else:
                    i += 1
                continue
        pos.append(t); i += 1
    # Conflicts after full parse, matching clap's first-conflicting-argument wording reasonably.
    def conflict(a: str, b: str):
        if seen.get(a) and seen.get(b):
            first = a if seen_order.index(specs[a].usage) < seen_order.index(specs[b].usage) else b
            second = b if first == a else a
            opt1 = specs[first].usage
            opt2 = specs[second].usage
            usage = usage_with_option(command, opt1, bool(pos))
            parse_error(f"the argument '{opt1}' cannot be used with '{opt2}'", usage_suffix=usage)
    if command in {"stash", "enqueue", "start", "pause", "kill", "wait"}:
        conflict("all", "group")
    if command == "restart":
        conflict("all-failed", "failed-in-group")
        conflict("immediate", "stashed")
    if max_pos is not None and len(pos) > max_pos:
        unexpected(pos[max_pos], usage_key=command, value_tip=False)
    if len(pos) < required_min:
        if pos_kind == "remove":
            missing_required(["<TASK_IDS>..."], USAGE[command])
        elif pos_kind == "switch":
            missing_required(["<TASK_ID_1>", "<TASK_ID_2>"][len(pos):], USAGE[command])
        elif pos_kind == "send":
            missing_required(["<TASK_ID>", "<INPUT>"][len(pos):], USAGE[command])
        else:
            missing_required([pos_kind], USAGE[command])
    if numeric:
        validate_task_list(pos, command)


def parse_add(args: List[str]) -> None:
    specs: Dict[str, OptSpec] = {}
    def add(long: str, usage: str, short: Optional[str] = None, takes: bool = False,
            validator: Optional[Callable[[str, str], None]] = None):
        specs[long] = OptSpec(long, usage, short, takes, validator, flag=not takes)
    add("working-directory", "--working-directory <working-directory>", "w", True)
    add("escape", "--escape", "e")
    add("immediate", "--immediate", "i")
    add("follow", "--follow")
    add("stashed", "--stashed", "s")
    add("delay", "--delay <delay>", "d", True, validate_delay)
    add("group", "--group <GROUP>", "g", True)
    add("after", "--after <after>...", "a", True, validate_uint)
    add("priority", "--priority <PRIORITY>", "o", True, validate_uint)
    add("label", "--label <LABEL>", "l", True)
    add("print-task-id", "--print-task-id", "p")
    seen: Dict[str, bool] = {}
    seen_order: List[str] = []
    command_started = False
    command_vals: List[str] = []
    after_dd = False
    i = 0
    while i < len(args):
        t = args[i]
        if command_started or after_dd:
            command_vals.extend(args[i:])
            i = len(args)
            break
        if t == "--":
            after_dd = True; i += 1; continue
        if t == "--help":
            print_help("add", True)
        if t == "-h":
            print_help("add", False)
        if t.startswith("--"):
            nameval = t[2:]
            name, eq, value = nameval.partition("=")
            spec = specs.get(name)
            if spec is None:
                unexpected(t, usage_key="add", value_tip=True)
            if spec.takes:
                if name == "after" and not eq:
                    # --after/-a greedily consumes non-option values until the next option or --.
                    vals: List[str] = []
                    j = i + 1
                    if j >= len(args) or args[j] == "--":
                        missing_value(spec.usage)
                    if args[j].startswith("-"):
                        unexpected(args[j], usage_key="add", value_tip=True)
                    while j < len(args) and args[j] != "--" and not args[j].startswith("-"):
                        vals.append(args[j]); j += 1
                    if not vals:
                        missing_value(spec.usage)
                    for val in vals:
                        spec.validator(val, spec.usage)  # type: ignore
                    i = j
                else:
                    if eq:
                        val = value; i += 1
                    else:
                        val, i = get_option_value(args, i, spec, "add", True)
                    if spec.validator:
                        spec.validator(val, spec.usage)
                seen[name] = True; seen_order.append(spec.usage)
            else:
                if eq:
                    unexpected_value(value, f"--{name}", usage_with_option("add", spec.usage))
                seen[name] = True; seen_order.append(spec.usage); i += 1
            continue
        if t.startswith("-") and t != "-":
            j = 1
            while j < len(t):
                ch = t[j]
                if ch == "h":
                    print_help("add", False)
                spec = spec_by_short(specs, ch)
                if spec is None:
                    unexpected("-" + ch if len(t) > 2 else t, usage_key="add", value_tip=True)
                if spec.takes:
                    if spec.long == "after" and j + 1 >= len(t):
                        vals: List[str] = []
                        k = i + 1
                        if k >= len(args) or args[k] == "--":
                            missing_value(spec.usage)
                        if args[k].startswith("-"):
                            unexpected(args[k], usage_key="add", value_tip=True)
                        while k < len(args) and args[k] != "--" and not args[k].startswith("-"):
                            vals.append(args[k]); k += 1
                        for val in vals:
                            spec.validator(val, spec.usage)  # type: ignore
                        i = k
                    else:
                        if j + 1 < len(t):
                            val = t[j+1:]; i += 1
                        else:
                            val, i = get_option_value(args, i, spec, "add", True)
                        if spec.validator:
                            spec.validator(val, spec.usage)
                    seen[spec.long] = True; seen_order.append(spec.usage)
                    break
                else:
                    seen[spec.long] = True; seen_order.append(spec.usage); j += 1
            else:
                i += 1
            continue
        command_started = True
        command_vals.extend(args[i:])
        break
    # Conflicts/requirements.
    if seen.get("immediate") and seen.get("stashed"):
        first = "immediate" if seen_order.index("--immediate") < seen_order.index("--stashed") else "stashed"
        second = "stashed" if first == "immediate" else "immediate"
        usage = usage_with_option("add", specs[first].usage)
        parse_error(f"the argument '{specs[first].usage}' cannot be used with '{specs[second].usage}'", usage_suffix=usage)
    if seen.get("follow") and not seen.get("immediate"):
        parse_error("the following required arguments were not provided:\n  --immediate",
                    usage_suffix="add --immediate --follow <COMMAND>...")
    if not command_vals:
        parts = []
        for u in seen_order:
            if u not in parts:
                parts.append(u)
        usage = "add " + (" ".join(parts) + " " if parts else "") + "<COMMAND>..."
        missing_required(["<COMMAND>..."], usage)


def parse_group_add(args: List[str]) -> None:
    parallel_seen = False
    pos: List[str] = []
    after_dd = False
    i = 0
    while i < len(args):
        t = args[i]
        if after_dd:
            pos.append(t); i += 1; continue
        if t == "--":
            after_dd = True; i += 1; continue
        if t == "--help":
            print_help("group_add", True)
        if t == "-h":
            print_help("group_add", False)
        if t in ("-p", "--parallel") or t.startswith("--parallel=") or (t.startswith("-p") and len(t) > 2):
            spec = OptSpec("parallel", "--parallel <PARALLEL>", "p", True, validate_uint)
            if t.startswith("--parallel="):
                val = t.split("=", 1)[1]; i += 1
            elif t.startswith("-p") and len(t) > 2:
                val = t[2:]; i += 1
            else:
                val, i = get_option_value(args, i, spec, "group_add", True)
            validate_uint(val, spec.usage)
            parallel_seen = True
            continue
        if t.startswith("-") and t != "-":
            unexpected(t, usage_key="group_add", value_tip=True)
        pos.append(t); i += 1
    if len(pos) > 1:
        unexpected(pos[1], usage_key="group_add")
    if len(pos) < 1:
        usage = "group add" + (" --parallel <PARALLEL>" if parallel_seen else "") + " <NAME>"
        missing_required(["<NAME>"], usage)


def parse_fixed_positions(key: str, args: List[str], names: List[str], numeric_indices: List[int],
                          allow_options: bool = True) -> None:
    pos: List[str] = []
    after_dd = False
    i = 0
    while i < len(args):
        t = args[i]
        if after_dd:
            pos.append(t); i += 1; continue
        if t == "--":
            after_dd = True; i += 1; continue
        if allow_options and t == "--help":
            print_help(key, True)
        if allow_options and t == "-h":
            print_help(key, False)
        if t.startswith("-") and t != "-":
            unexpected(t, usage_key=key, value_tip=True)
        pos.append(t); i += 1
    if len(pos) > len(names):
        unexpected(pos[len(names)], usage_key=key)
    if len(pos) < len(names):
        missing_required(names[len(pos):], USAGE[key])
    for idx in numeric_indices:
        validate_uint(pos[idx], names[idx])


def parse_group(args: List[str]) -> None:
    i = 0
    after_dd = False
    while i < len(args):
        t = args[i]
        if after_dd:
            unexpected(t, usage_key="group")
        if t == "--":
            after_dd = True; i += 1; continue
        if t == "--help":
            print_help("group", True)
        if t == "-h":
            print_help("group", False)
        if t in ("-j", "--json"):
            i += 1; continue
        if t.startswith("--json="):
            unexpected_value(t.split("=", 1)[1], "--json", "group --json [COMMAND]")
        if t.startswith("-") and t != "-":
            unexpected(t, usage_key="group")
        # subcommand
        sub = t
        rest = args[i+1:]
        if sub == "help":
            handle_nested_help("group", rest)
            return
        if sub == "add":
            parse_group_add(rest); return
        if sub == "remove":
            parse_fixed_positions("group_remove", rest, ["<NAME>"], [], True); return
        unrecognized_subcommand(sub, "group", ["add", "remove", "help"])
    # No subcommand: valid daemon command.


def parse_env(args: List[str]) -> None:
    if not args:
        print_help("env", False, to_stderr=True)
    t = args[0]
    if t == "--help":
        print_help("env", True)
    if t == "-h":
        print_help("env", False)
    if t.startswith("-") and t != "-":
        unexpected(t, usage_key="env")
    rest = args[1:]
    if t == "help":
        handle_nested_help("env", rest)
        return
    if t == "set":
        parse_fixed_positions("env_set", rest, ["<TASK_ID>", "<KEY>", "<VALUE>"], [0], True); return
    if t == "unset":
        parse_fixed_positions("env_unset", rest, ["<TASK_ID>", "<KEY>"], [0], True); return
    unrecognized_subcommand(t, "env", ["set", "unset", "help"])


def handle_nested_help(parent: str, rest: List[str]) -> None:
    if parent == "env":
        if not rest:
            print_help("env", True)
        topic = rest[0]
        if topic == "set" and len(rest) == 1:
            print_help("env_set", True)
        if topic == "unset" and len(rest) == 1:
            print_help("env_unset", True)
        if len(rest) > 1 and topic in {"set", "unset"}:
            usage_key = "env_set" if topic == "set" else "env_unset"
            unrecognized_subcommand(rest[1], usage_key, [])
        unrecognized_subcommand(topic, "env", ["set", "unset", "help"])
    if parent == "group":
        if not rest:
            print_help("group", True)
        topic = rest[0]
        if topic == "add" and len(rest) == 1:
            print_help("group_add", True)
        if topic == "remove" and len(rest) == 1:
            print_help("group_remove", True)
        if len(rest) > 1 and topic in {"add", "remove"}:
            usage_key = "group_add" if topic == "add" else "group_remove"
            unrecognized_subcommand(rest[1], usage_key, [])
        unrecognized_subcommand(topic, "group", ["add", "remove", "help"])


def parse_completions(args: List[str]) -> Optional[Tuple[str, Optional[str]]]:
    pos: List[str] = []
    after_dd = False
    i = 0
    while i < len(args):
        t = args[i]
        if after_dd:
            pos.append(t); i += 1; continue
        if t == "--":
            after_dd = True; i += 1; continue
        if t == "--help":
            print_help("completions", True)
        if t == "-h":
            print_help("completions", False)
        if t.startswith("-") and t != "-":
            unexpected(t, usage_key="completions", value_tip=True)
        pos.append(t); i += 1
    if not pos:
        missing_required(["<SHELL>"], USAGE["completions"])
    if len(pos) > 2:
        unexpected(pos[2], usage_key="completions")
    shell = pos[0]
    if shell not in SHELLS:
        tip = suggest_value(shell, SHELLS)
        tip_text = f"a similar value exists: '{tip}'" if tip else None
        # clap's invalid enum wording omits a colon/reason after the target.
        parse_error(f"invalid value '{shell}' for '<SHELL>'",
                    possible=", ".join(SHELLS), tip=tip_text)
    return shell, (pos[1] if len(pos) == 2 else None)


def generate_completions(shell: str, out_dir: Optional[str]) -> None:
    _, comp_dir = data_dirs()
    data = (comp_dir / f"{shell}.txt").read_bytes()
    if out_dir is None:
        sys.stdout.buffer.write(data)
        return
    target = Path(out_dir) / SHELL_FILES[shell]
    try:
        with open(target, "wb") as f:
            f.write(data)
    except OSError as e:
        msg = os_error_text(e)
        runtime_error([f"Failed to generate completions for {SHELL_DISPLAY[shell]}", msg],
                      "pueue/src/bin/pueue.rs", 125)


def os_error_text(e: OSError) -> str:
    err_no = e.errno if e.errno is not None else errno.EIO
    # Python's strerror matches the observed Linux wording for the errors we need.
    return f"{e.strerror} (os error {err_no})"


def data_home() -> str:
    xdg = os.environ.get("XDG_DATA_HOME")
    if xdg:
        return xdg
    home = os.environ.get("HOME", str(Path.home()))
    return os.path.join(home, ".local", "share")


def config_home() -> str:
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return xdg
    home = os.environ.get("HOME", str(Path.home()))
    return os.path.join(home, ".config")


def log_info(msg: str, verbose: int) -> None:
    ts = time.strftime("%H:%M:%S")
    if verbose >= 4:
        sys.stderr.write(f"  {DIM}{ts}{RESET} {GREEN} INFO{RESET} {BOLD_GREEN}pueue_lib::settings{RESET}{GREEN}: {GREEN}{msg}{RESET}\n")
        line = 391 if msg == "Parsing config files" else (413 if msg == "No config file found. Use default config." else 396)
        sys.stderr.write(f"    {DIM_ITALIC}at{RESET} pueue_lib/src/settings.rs:{line} {DIM_ITALIC}on{RESET} main\n\n")
    elif verbose > 0:
        sys.stderr.write(f"{DIM}{ts}{RESET} {GREEN} INFO{RESET} {DIM}pueue_lib::settings{RESET}{DIM}:{RESET} {msg}\n")


def check_config_syntax(path: str) -> Optional[str]:
    try:
        content = Path(path).read_text()
    except OSError as e:
        return f"I/O error at path \"{path}\" while opening config file:\n      {os_error_text(e)}"
    stripped = content.lstrip()
    if stripped.startswith("["):
        return "Error while reading configuration:\n      invalid type: sequence, expected struct Settings"
    if re.search(r":\s*\[\s*$", content):
        return "Error while reading configuration:\n      did not find expected node content at line 2 column 1, while parsing a flow node"
    return None


def find_config(config_opt: Optional[str], verbose: int) -> Tuple[bool, Optional[str], Optional[str]]:
    # returns (found, path, error_message)
    if config_opt:
        err = check_config_syntax(config_opt)
        if err:
            return False, config_opt, err
        return True, config_opt, None
    env_path = os.environ.get("PUEUE_CONFIG_PATH")
    if env_path:
        err = check_config_syntax(env_path)
        if err:
            return False, env_path, err
        return True, env_path, None
    log_info("Parsing config files", verbose)
    paths = [os.path.join(config_home(), "pueue", "pueue.yml"), "./pueue.yml"]
    for p in paths:
        display = p
        log_info(f"Checking path: \"{display}\"", verbose)
        if os.path.exists(p):
            log_info(f"Found config file at: \"{display}\"", verbose)
            err = check_config_syntax(p)
            if err:
                return False, p, err
            return True, p, None
    log_info("No config file found. Use default config.", verbose)
    return False, None, None


def runtime_error(chain: List[str], location: str, line: int) -> None:
    out = ["Error: \n"]
    for i, msg in enumerate(chain):
        out.append(f"   {i}: {RED}{msg}{RESET}\n")
    out.append("\nLocation:\n")
    out.append(f"   {MAGENTA}{location}{RESET}:{MAGENTA}{line}{RESET}\n\n")
    # The observed default color-eyre report.
    rb = os.environ.get("RUST_BACKTRACE")
    if rb and rb not in {"0", "false", "False"}:
        out.append("Stack backtrace:\n   <disabled in this reimplementation>\n")
    else:
        out.append("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n")
        out.append("Run with RUST_BACKTRACE=full to include source snippets.\n")
    sys.stderr.write("".join(out))
    raise CliExit(1)


def runtime_no_daemon(global_opts: Dict[str, object]) -> None:
    verbose = int(global_opts.get("verbose", 0) or 0)
    config_opt = global_opts.get("config")
    profile = global_opts.get("profile")
    found, path, cfg_err = find_config(str(config_opt) if config_opt else None, verbose)
    if cfg_err:
        runtime_error(["Failed to read configuration.", cfg_err], "pueue/src/bin/pueue.rs", 51)
    if profile:
        runtime_error([f"Error while reading configuration:\n      Couldn't find profile with name \"{profile}\""],
                      "pueue/src/bin/pueue.rs", 55)
    if not found:
        runtime_error(["Couldn't find a configuration file. Did you start the daemon yet?"],
                      "pueue/src/bin/pueue.rs", 61)
    secret = os.path.join(data_home(), "pueue", "shared_secret")
    try:
        Path(secret).read_bytes()
    except OSError as e:
        runtime_error([f"I/O error at path \"{secret}\" while opening secret file. Did you start the daemon at least once?:\n      {os_error_text(e)}"],
                      "pueue/src/bin/pueue.rs", 91)
    user = os.environ.get("USER") or getpass.getuser() or "agent"
    socket = os.path.join(data_home(), "pueue", f"pueue_{user}.socket")
    if not os.path.exists(socket):
        e = FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT), socket)
        runtime_error(["Failed to initialize client.", "Failed to initialize stream.",
                       f"I/O error at path \"{socket}\" while connecting to daemon. Did you start it?:\n      {os_error_text(e)}"],
                      "/workspace/pueue_lib/src/network/client.rs", 85)
    # If a socket-like path exists, still fail like a refused/non-socket connection.
    runtime_error(["Failed to initialize client.", "Failed to initialize stream.",
                   f"I/O error at path \"{socket}\" while connecting to daemon. Did you start it?:\n      Connection refused (os error 111)"],
                  "/workspace/pueue_lib/src/network/client.rs", 85)


def parse_root(argv: List[str]) -> Tuple[Optional[str], List[str], Dict[str, object], Optional[Tuple[str, Optional[str]]]]:
    opts: Dict[str, object] = {"verbose": 0, "color": "auto", "config": None, "profile": None}
    i = 0
    while i < len(argv):
        t = argv[i]
        if t == "--":
            if i + 1 < len(argv):
                val = argv[i+1]
                tip = None
                if normalize_command(val) in ROOT_COMMANDS or val in ROOT_ALIASES:
                    tip = f"subcommand '{val}' exists; to use it, remove the '--' before it"
                unexpected(val, usage_key="root", custom_tip=tip)
            # Bare --: no subcommand, but clap treats as no args? observed not needed.
            i += 1
            continue
        if t == "--help":
            print_help("root", True)
        if t == "-h":
            print_help("root", False)
        if t == "--version" or t == "-V":
            sys.stdout.write(VERSION + "\n")
            raise CliExit(0)
        if t.startswith("--"):
            nameval = t[2:]
            name, eq, value = nameval.partition("=")
            if name == "verbose":
                if eq:
                    unexpected_value(value, "--verbose", "[OPTIONS] [COMMAND]")
                opts["verbose"] = int(opts.get("verbose", 0) or 0) + 1; i += 1; continue
            if name in {"color", "config", "profile"}:
                usage = {"color": "--color <COLOR>", "config": "--config <CONFIG>", "profile": "--profile <PROFILE>"}[name]
                possible = "auto, never, always" if name == "color" else None
                if eq:
                    val = value
                    if name == "color" and val == "":
                        missing_value(usage, possible)
                    i += 1
                else:
                    if i + 1 >= len(argv) or argv[i+1] == "--":
                        missing_value(usage, possible)
                    if argv[i+1].startswith("-"):
                        unexpected(argv[i+1], usage_key="root")
                    val = argv[i+1]; i += 2
                if name == "color" and val not in {"auto", "never", "always"}:
                    invalid_value(val, usage, "", possible="auto, never, always")
                opts[name] = val; continue
            unexpected(t, usage_key="root")
        if t.startswith("-") and t != "-":
            # root short clusters: -vv, -cFILE, -pNAME, -vvc FILE.
            j = 1
            while j < len(t):
                ch = t[j]
                if ch == "h":
                    print_help("root", False)
                if ch == "V":
                    sys.stdout.write(VERSION + "\n"); raise CliExit(0)
                if ch == "v":
                    opts["verbose"] = int(opts.get("verbose", 0) or 0) + 1; j += 1; continue
                if ch in {"c", "p"}:
                    usage = "--config <CONFIG>" if ch == "c" else "--profile <PROFILE>"
                    key = "config" if ch == "c" else "profile"
                    if j + 1 < len(t):
                        val = t[j+1:]; i += 1
                    else:
                        if i + 1 >= len(argv) or argv[i+1] == "--":
                            missing_value(usage)
                        if argv[i+1].startswith("-"):
                            unexpected(argv[i+1], usage_key="root")
                        val = argv[i+1]; i += 2
                    opts[key] = val
                    break
                unexpected("-" + ch if len(t) > 2 else t, usage_key="root")
            else:
                i += 1
            continue
        # First non-option is command.
        cmd_raw = t
        cmd = normalize_command(cmd_raw)
        rest = argv[i+1:]
        if cmd == "help":
            handle_root_help(rest)
            raise AssertionError("unreachable")
        if cmd not in ROOT_COMMANDS:
            unrecognized_subcommand(cmd_raw, "root", [c for c in ROOT_COMMANDS if c != "help"], list(ROOT_ALIASES.keys()))
        if cmd == "completions":
            comp = parse_completions(rest)
            return cmd, rest, opts, comp
        parse_command(cmd, rest)
        return cmd, rest, opts, None
    # No command defaults to status at runtime.
    return None, [], opts, None


def handle_root_help(rest: List[str]) -> None:
    if not rest:
        print_help("root", True)
    topic = normalize_command(rest[0])
    if topic in ROOT_COMMANDS and topic != "help":
        if len(rest) == 1:
            print_help(topic, True)
        if topic == "env":
            if rest[1] == "set" and len(rest) == 2:
                print_help("env_set", True)
            if rest[1] == "unset" and len(rest) == 2:
                print_help("env_unset", True)
            if len(rest) > 2 and rest[1] in {"set", "unset"}:
                unrecognized_subcommand(rest[2], "env_set" if rest[1] == "set" else "env_unset", [])
            unrecognized_subcommand(rest[1], "env", ["set", "unset", "help"])
        if topic == "group":
            if rest[1] == "add" and len(rest) == 2:
                print_help("group_add", True)
            if rest[1] == "remove" and len(rest) == 2:
                print_help("group_remove", True)
            if len(rest) > 2 and rest[1] in {"add", "remove"}:
                unrecognized_subcommand(rest[2], "group_add" if rest[1] == "add" else "group_remove", [])
            unrecognized_subcommand(rest[1], "group", ["add", "remove", "help"])
        unrecognized_subcommand(rest[1], topic, [])
    # Note: `help --help` is an unrecognized subcommand, not help for help.
    unrecognized_subcommand(rest[0], "root", [c for c in ROOT_COMMANDS if c != "help"], list(ROOT_ALIASES.keys()))


def parse_command(cmd: str, rest: List[str]) -> None:
    if cmd == "add":
        parse_add(rest); return
    if cmd == "remove":
        parse_generic_command("remove", rest, "remove", 1, None, True, "remove", True); return
    if cmd == "switch":
        parse_fixed_positions("switch", rest, ["<TASK_ID_1>", "<TASK_ID_2>"], [0,1], True); return
    if cmd == "send":
        parse_fixed_positions("send", rest, ["<TASK_ID>", "<INPUT>"], [0], True); return
    if cmd == "edit":
        parse_generic_command("edit", rest, "[TASK_IDS]...", 0, None, True, "edit", True); return
    if cmd == "env":
        parse_env(rest); return
    if cmd == "group":
        parse_group(rest); return
    if cmd == "status":
        parse_generic_command("status", rest, "[QUERY]...", 0, None, False, "status", True); return
    if cmd == "log":
        parse_generic_command("log", rest, "[TASK_IDS]...", 0, None, True, "log", True); return
    if cmd == "follow":
        parse_generic_command("follow", rest, "[TASK_ID]", 0, 1, True, "follow", True); return
    if cmd == "clean":
        parse_generic_command("clean", rest, "", 0, 0, False, "clean", False); return
    if cmd == "reset":
        parse_generic_command("reset", rest, "", 0, 0, False, "reset", False); return
    if cmd == "shutdown":
        # Only help is accepted.
        parse_fixed_positions("shutdown", rest, [], [], True); return
    if cmd == "parallel":
        parse_generic_command("parallel", rest, "[PARALLEL_TASKS]", 0, 1, True, "parallel", True); return
    if cmd in {"stash", "enqueue", "start", "restart", "pause", "kill", "wait"}:
        parse_generic_command(cmd, rest, "[TASK_IDS]...", 0, None, True, cmd, True); return
    raise AssertionError(cmd)


def main(argv: List[str]) -> int:
    try:
        cmd, rest, opts, comp = parse_root(argv)
        if cmd == "completions" and comp is not None:
            generate_completions(comp[0], comp[1])
            return 0
        runtime_no_daemon(opts)
        return 1
    except CliExit as e:
        return e.code

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
